1	package credentials
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"os/exec"
8		"strings"
9		"testing"
10	
11		"github.com/zalando/go-keyring"
12	)
13	
14	// errSentinelHost is what the mocked go-keyring answers when the guard is
15	// broken: a guard that does not fire lets this error reach the caller, so a
16	// test sees "no panic" instead of touching the real host store.
17	var errSentinelHost = errors.New("sentinel: the real host store must never be reached")
18	
19	// useGoKeyring makes the production adapter the store in use, and restores the
20	// previous one at cleanup. It does not call go-keyring.
21	func useGoKeyring(t *testing.T) {
22		t.Helper()
23		prev := SwapHostStoreForTest(goKeyring{})
24		t.Cleanup(func() { SwapHostStoreForTest(prev) })
25	}
26	
27	// withoutAuthorization withdraws the TestMain authorization, as in any package
28	// that did not isolate the host store, and restores it at cleanup.
29	func withoutAuthorization(t *testing.T) {
30		t.Helper()
31		prev := hostReachableUnderTest.Swap(false)
32		t.Cleanup(func() { hostReachableUnderTest.Store(prev) })
33	}
34	
35	// recoverMessage runs fn and returns the text of its panic, or "" and false
36	// when fn returned normally.
37	func recoverMessage(fn func()) (msg string, panicked bool) {
38		defer func() {
39			if r := recover(); r != nil {
40				msg, panicked = fmt.Sprint(r), true
41			}
42		}()
43		fn()
44		return "", false
45	}
46	
47	func TestHostStoreGuardPanicsUnderTest(t *testing.T) {
48		tests := []struct {
49			name string
50			call func()
51			op   string // must appear in the panic message
52		}{
53			{"KeyringAvailable", func() { KeyringAvailable() }, "keyring get"},
54			{"Save", func() { _ = NewKeyringStorage("ctx").Save("https://h.example", "secret") }, "keyring set"},
55			{"Load", func() { _, _ = NewKeyringStorage("ctx").Load("https://h.example") }, "keyring get"},
56			{"Delete", func() { _ = NewKeyringStorage("ctx").Delete("https://h.example") }, "keyring delete"},
57			{"runCredential", func() { _, _ = runCredential("fill", "protocol=https\nhost=h.example\n\n") }, "git credential fill"},
58		}
59		for _, tt := range tests {
60			t.Run(tt.name, func(t *testing.T) {
61				// Even if the guard is broken, nothing below reaches the real store:
62				// go-keyring answers with an error instead.
63				keyring.MockInitWithError(errSentinelHost)
64				useGoKeyring(t)
65				withoutAuthorization(t)
66	
67				msg, panicked := recoverMessage(tt.call)
68				if !panicked {
69					t.Fatalf("%s did not panic: the host store is reachable from a test without isolation", tt.name)
70				}
71				for _, want := range []string{"DEVDESK-610", "fakekeyring", tt.op} {
72					if !strings.Contains(msg, want) {
73						t.Errorf("panic message %q does not contain %q", msg, want)
74					}
75				}
76			})
77		}
78	}
79	
80	func TestHostStoreGuardStandsDownWhenAuthorized(t *testing.T) {
81		keyring.MockInit()
82		useGoKeyring(t)
83		// hostReachableUnderTest is true here, set by TestMain.
84		if msg, panicked := recoverMessage(func() { KeyringAvailable() }); panicked {
85			t.Fatalf("KeyringAvailable panicked although this package is authorized: %s", msg)
86		}
87	}
88	
89	// TestHostStoreGuardFailsTheTestThatReachesIt checks the property the story is
90	// about: the failure names the test that reached the store. It runs the helper
91	// below in a child test binary, because the helper's panic is the failure.
92	func TestHostStoreGuardFailsTheTestThatReachesIt(t *testing.T) {
93		cmd := exec.Command(os.Args[0], "-test.run=^TestHostStoreGuardHelper$")
94		cmd.Env = append(os.Environ(),
95			"DEVDESK_HOSTSTORE_GUARD_HELPER=1",
96			// Never let the child look for a session bus, even if the guard is broken.
97			"DBUS_SESSION_BUS_ADDRESS=unix:path=/nonexistent",
98		)
99		out, err := cmd.CombinedOutput()
100		var exitErr *exec.ExitError
101		if !errors.As(err, &exitErr) {
102			t.Fatalf("the helper test exited cleanly (err = %v); the guard did not fail it\n%s", err, out)
103		}
104		for _, want := range []string{"--- FAIL: TestHostStoreGuardHelper", "DEVDESK-610"} {
105			if !strings.Contains(string(out), want) {
106				t.Errorf("output does not contain %q\n%s", want, out)
107			}
108		}
109	}
110	
111	// TestHostStoreGuardHelper is the test that reaches the store without
112	// isolation. It only runs as the child of the test above.
113	func TestHostStoreGuardHelper(t *testing.T) {
114		if os.Getenv("DEVDESK_HOSTSTORE_GUARD_HELPER") != "1" {
115			t.Skip("child of TestHostStoreGuardFailsTheTestThatReachesIt")
116		}
117		keyring.MockInitWithError(errSentinelHost)
118		useGoKeyring(t)
119		withoutAuthorization(t)
120		Select("x", PreferenceAuto)
121	}
122	
123	// recordingHost is a HostStore that remembers it was called.
124	type recordingHost struct {
125		err   error // returned by every operation when set
126		miss  bool  // Get reports a missing entry
127		calls int
128	}
129	
130	func (r *recordingHost) Get(service, account string) (string, error) {
131		r.calls++
132		if r.err != nil {
133			return "", r.err
134		}
135		if r.miss {
136			return "", fmt.Errorf("%w: %s/%s", ErrNotFound, service, account)
137		}
138		return "value", nil
139	}
140	
141	func (r *recordingHost) Set(service, account, secret string) error {
142		r.calls++
143		return r.err
144	}
145	
146	func (r *recordingHost) Delete(service, account string) error {
147		r.calls++
148		return r.err
149	}
150	
151	func TestSwapHostStoreForTestReplacesAndRestores(t *testing.T) {
152		// The guard must not fire for a swapped store, whatever the authorization.
153		withoutAuthorization(t)
154	
155		first := &recordingHost{miss: true}
156		second := &recordingHost{err: errors.New("locked")}
157	
158		orig := SwapHostStoreForTest(first)
159		t.Cleanup(func() { SwapHostStoreForTest(orig) })
160	
161		if !KeyringAvailable() {
162			t.Error("KeyringAvailable() = false on a store that answers with a miss, want true")
163		}
164		if sel := Select("ctx", PreferenceAuto); sel.Backend != BackendKeyring {
165			t.Errorf("Select() backend = %q, want %q", sel.Backend, BackendKeyring)
166		}
167		if first.calls == 0 {
168			t.Error("the swapped store was never called")
169		}
170	
171		if got := SwapHostStoreForTest(second); got != HostStore(first) {
172			t.Errorf("SwapHostStoreForTest returned %v, want the store it replaced", got)
173		}
174		if KeyringAvailable() {
175			t.Error("KeyringAvailable() = true on a store that fails, want false")
176		}
177		// Pinned to the keyring, an unreachable store falls through to memory.
178		if sel := Select("ctx", PreferenceKeyring); sel.Backend != BackendMemory {
179			t.Errorf("Select(keyring) on a failing store = %q, want %q", sel.Backend, BackendMemory)
180		}
181	
182		if got := SwapHostStoreForTest(first); got != HostStore(second) {
183			t.Errorf("SwapHostStoreForTest returned %v, want the second store", got)
184		}
185	}
186	
187	func TestKeyringStorageMapsTheGoKeyringMiss(t *testing.T) {
188		keyring.MockInit()
189		useGoKeyring(t)
190	
191		_, err := NewKeyringStorage("ctx").Load("https://absent.example")
192		if !errors.Is(err, ErrNotFound) {
193			t.Errorf("Load() of a missing entry = %v, want an error for which errors.Is(err, ErrNotFound)", err)
194		}
195		if err := NewKeyringStorage("ctx").Delete("https://absent.example"); err != nil {
196			t.Errorf("Delete() of a missing entry = %v, want nil", err)
197		}
198	}
